@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @FilteredTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
        <span class="stat-item"><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
        <span class="stat-item"><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @FilteredTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="board-container">
        @foreach (var column in _columns)
        {
            var tasks = GetColumnTasks(column);
            <div class="board-column">
                <div class="column-header">
                    <h3>@column <span class="badge bg-secondary">@tasks.Count</span></h3>
                </div>
                <div class="column-body">
                    @foreach (var task in tasks)
                    {
                        <div class="task-card">
                            <div class="task-title">@task.Title</div>
                            <div class="task-assignee">@task.Assignee</div>
                            <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                            <div class="task-actions">
                                @if (GetColumnIndex(column) > 0)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTask(task.Id, _columns[GetColumnIndex(column) - 1])">
                                        &larr; Move Left
                                    </button>
                                }
                                @if (GetColumnIndex(column) < _columns.Length - 1)
                                {
                                    <button class="btn btn-sm btn-outline-secondary"
                                            @onclick="() => MoveTask(task.Id, _columns[GetColumnIndex(column) + 1])">
                                        Move Right &rarr;
                                    </button>
                                }
                            </div>
                        </div>
                    }
                </div>
                <div class="column-footer">
                    @if (_addingToColumn == column)
                    {
                        <div class="add-task-form">
                            <input type="text" class="form-control mb-1" placeholder="Title"
                                   @bind="_newTitle" />
                            <input type="text" class="form-control mb-1" placeholder="Assignee"
                                   @bind="_newAssignee" />
                            <select class="form-select mb-1" @bind="_newPriority">
                                <option value="High">High</option>
                                <option value="Medium">Medium</option>
                                <option value="Low">Low</option>
                            </select>
                            <input type="date" class="form-control mb-1" @bind="_newDueDate" />
                            <div class="d-flex gap-1">
                                <button class="btn btn-sm btn-primary" @onclick="() => SaveTask(column)">Save</button>
                                <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
                            </div>
                        </div>
                    }
                    else
                    {
                        <button class="btn btn-sm btn-outline-primary w-100"
                                @onclick="() => StartAdd(column)">
                            + Add Task
                        </button>
                    }
                </div>
            </div>
        }
    </div>
}

<style>
    .stats-bar {
        display: flex;
        gap: 1.5rem;
        padding: 0.75rem 1rem;
        background: #f8f9fa;
        border-radius: 0.5rem;
        margin-bottom: 1rem;
        flex-wrap: wrap;
    }

    .stat-overdue {
        color: #dc3545;
    }

    .search-bar {
        margin-bottom: 1rem;
        max-width: 400px;
    }

    .board-container {
        display: flex;
        gap: 1rem;
        align-items: flex-start;
    }

    .board-column {
        flex: 1;
        min-width: 250px;
        background: #f1f3f5;
        border-radius: 0.5rem;
        padding: 0.75rem;
        display: flex;
        flex-direction: column;
    }

    .column-header h3 {
        font-size: 1.1rem;
        margin-bottom: 0.5rem;
    }

    .column-body {
        flex: 1;
        display: flex;
        flex-direction: column;
        gap: 0.5rem;
        margin-bottom: 0.75rem;
    }

    .task-card {
        background: #fff;
        border: 1px solid #dee2e6;
        border-radius: 0.375rem;
        padding: 0.75rem;
    }

    .task-title {
        font-weight: 600;
        margin-bottom: 0.25rem;
    }

    .task-assignee {
        font-size: 0.85rem;
        color: #6c757d;
        margin-bottom: 0.25rem;
    }

    .task-due {
        font-size: 0.85rem;
        color: #495057;
        margin-top: 0.25rem;
    }

    .priority-badge {
        display: inline-block;
        padding: 0.15rem 0.5rem;
        border-radius: 0.25rem;
        font-size: 0.75rem;
        font-weight: 600;
        color: #fff;
    }

    .priority-high {
        background-color: #dc3545;
    }

    .priority-medium {
        background-color: #ffc107;
        color: #212529;
    }

    .priority-low {
        background-color: #198754;
    }

    .task-actions {
        margin-top: 0.5rem;
        display: flex;
        gap: 0.25rem;
    }

    .column-footer {
        margin-top: auto;
    }

    .add-task-form {
        background: #fff;
        border: 1px solid #dee2e6;
        border-radius: 0.375rem;
        padding: 0.75rem;
    }
</style>

@code {
    private readonly string[] _columns = { "To Do", "In Progress", "Done" };
    private List<TaskItem> _tasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchText = string.Empty;

    // Add task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);

    private List<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(_searchText)
            ? _tasks
            : _tasks.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> GetColumnTasks(string status) =>
        FilteredTasks.Where(t => t.Status == status).ToList();

    private int GetColumnIndex(string column) => Array.IndexOf(_columns, column);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _tasks.First(t => t.Id == taskId);
            _tasks = _tasks.Select(t => t.Id == taskId ? task with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd()
    {
        _addingToColumn = null;
    }

    private async Task SaveTask(string column)
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // The service creates with default status; update to target column if needed
            if (created.Status != column)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, column);
                created = created with { Status = column };
            }
            _tasks.Add(created);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }
}

